<?php declare(strict_types=1);namespace App\Modules\ProjectCosts\Controllers;use App\Core\Http\Request;use App\Core\Http\Response;use App\Modules\ProjectCosts\Services\ProjectCostService;use App\Modules\ProjectCosts\Validators\ProjectCostTableQueryValidator;final class ProjectCostDataTableController{public function __construct(private readonly ProjectCostService$costs,private readonly ProjectCostTableQueryValidator$validator){}public function global(Request$r):Response{return Response::json($this->costs->dataTable($this->validator->validate($r->all())));}public function project(Request$r):Response{return Response::json($this->costs->dataTable($this->validator->validate($r->all(),(int)$r->route('project_id'))));}}
